// Chat profanity filter. Masks listed words with asterisks of the same length.
// Word list: LDNOOBW "List-of-Dirty-Naughty-Obscene-and-Otherwise-Bad-Words"
// (English), licensed CC BY 4.0 (https://creativecommons.org/licenses/by/4.0/).
// The list lives in profanity-words.ts, generated by tools/profanity/gen.mjs.
//
// A word is matched only as a whole token, never as a substring, so words such
// as "assistant", "classic" or "Scunthorpe" pass untouched. Tokens are compared
// after case folding, accent stripping and leetspeak substitution, so "f\u00fcck",
// "sh1t" and "a$$" are caught too. Links are not words and are skipped.

import { PROFANITY_WORDS } from "./profanity-words";

const LEET: Record<string, string> = {
  "@": "a",
  "$": "s",
  "0": "o",
  "1": "i",
  "3": "e",
  "4": "a",
  "5": "s",
  "7": "t",
  "8": "b",
  "9": "g",
};

/** A word in its comparison form: lowercase, no accents, leetspeak undone. */
function fold(s: string): string {
  return s
    .toLowerCase()
    .normalize("NFD")
    .replace(/\p{M}/gu, "")
    .replace(/[@$0-9]/g, (c) => LEET[c] ?? c);
}

const BAD = new Set(PROFANITY_WORDS.map(fold));
const MAX_WORDS = Math.max(1, ...PROFANITY_WORDS.map((w) => w.split(" ").length));

/** Letters, digits, marks and the characters leetspeak uses. */
const WORD = /[\p{L}\p{N}\p{M}@$&]+/gu;
/** Whitespace-delimited chunks that are links or domains; they are not words. */
const LINK = /\S*\/\S*|\bwww\.\S*/gi;

interface Token {
  start: number;
  end: number;
  key: string;
}

/** Masks every listed word or phrase in `text`; the result has the same length. */
export function filterProfanity(text: string): string {
  // Blanking links keeps every offset valid while they stop acting as words.
  const scanned = text.replace(LINK, (m) => " ".repeat(m.length));
  const tokens: Token[] = [...scanned.matchAll(WORD)].map((m) => ({
    start: m.index,
    end: m.index + m[0].length,
    key: fold(m[0]),
  }));

  const out: string[] = [];
  let copied = 0;
  for (let i = 0; i < tokens.length; i++) {
    const n = matchLength(scanned, tokens, i);
    if (n === 0) continue;
    const first = tokens[i];
    const last = tokens[i + n - 1];
    out.push(text.slice(copied, first.start), "*".repeat(last.end - first.start));
    copied = last.end;
    i += n - 1;
  }
  out.push(text.slice(copied));
  return out.join("");
}

/** Tokens from `i` spelling the longest listed word or phrase (0 if none). */
function matchLength(scanned: string, tokens: Token[], i: number): number {
  let key = tokens[i].key;
  let best = BAD.has(key) ? 1 : 0;
  for (let j = i + 1; j < tokens.length && j - i < MAX_WORDS; j++) {
    // A phrase is words separated by blanks only ("blow job", not "blow, job").
    if (!/^\s+$/.test(scanned.slice(tokens[j - 1].end, tokens[j].start))) break;
    key += ` ${tokens[j].key}`;
    if (BAD.has(key)) best = j - i + 1;
  }
  return best;
}
